export function getSubstitutes(exerciseId: string): ExerciseSubstitution | undefined {
  return SUBSTITUTION_MAP.find(s => s.exerciseId === exerciseId);
}

export function canReplace(exA: string, exB: string): boolean {
  const a = EXERCISE_CATALOG.find(e => e.id === exA);
  const b = EXERCISE_CATALOG.find(e => e.id === exB);
  if (!a || !b) return false;
  if (a.cannotReplace?.includes(exB)) return false;
  if (b.cannotReplace?.includes(exA)) return false;
  if (a.substitutionGroup && b.substitutionGroup && a.substitutionGroup === b.substitutionGroup) return true;
  if (a.canReplace?.includes(exB)) return true;
  return false;
}

export function getExerciseById(id: string): Exercise | undefined {
  return EXERCISE_CATALOG.find(e => e.id === id);
}

export function getExercisesByGroup(group: string): Exercise[] {
  return EXERCISE_CATALOG.filter(e => e.group === group);
}

export function getExercisesBySubstitutionGroup(sg: string): Exercise[] {
  return EXERCISE_CATALOG.filter(e => e.substitutionGroup === sg);
}